/** A latitude/longitude as a point on the map, or null when it is off the island's box. */
export function project(lat: number, lng: number): { x: number; y: number } | null {
  if (lat < S_LAT || lat > N_LAT || lng < W_LNG || lng > E_LNG) return null;
  return {
    x: ((lng - W_LNG) / (E_LNG - W_LNG)) * MAP_W,
    y: ((N_LAT - lat) / (N_LAT - S_LAT)) * MAP_H,
  };
}

/**
 * Phase → dot colour. Only the jobs being built or priced get a colour (owner,
 * 2026-11-01); every other phase is grey. The categorical --viz set
 * (globals.css), never the brand hue. Listed in the order a shared address
 * picks its colour — several jobs at one place draw one dot, in the phase that
 * matters most.
 */
export const PHASE_COLORS: { phase: string; color: string }[] = [
  { phase: "Active", color: "var(--viz-4)" },
  { phase: "PreCon", color: "var(--viz-2)" },
  { phase: "PreCon Budget", color: "var(--viz-2)" },
];
export const OTHER_PHASE_COLOR = "var(--viz-other)";

export interface MapJob {
  id: string;
  name: string;
  phase?: string | null;
  lat?: number | null;
  lng?: number | null;
  /** A number to print in the dot, summed per place (the Tools page: tools there). */
  count?: number;
}

export interface MapPlace {
  key: string;
  x: number;
  y: number;
  /** The phase the dot is painted in — the highest-ranked phase among its jobs. */
  phase: string | null;
  jobs: MapJob[];
}

const rank = (phase: string | null | undefined) => {
  const i = PHASE_COLORS.findIndex((p) => p.phase === phase);
  return i < 0 ? PHASE_COLORS.length : i;
};

export function phaseColor(phase: string | null | undefined): string {
  return PHASE_COLORS.find((p) => p.phase === phase)?.color ?? OTHER_PHASE_COLOR;
}

/**
 * Jobs grouped into one place per address. Jobs without coordinates, or off
 * Lopez, are left out and counted, so a caller can say how many the map misses.
 */
export function placeJobs(jobs: MapJob[]): { places: MapPlace[]; offMap: number } {
  const byKey = new Map<string, MapPlace>();
  let offMap = 0;
  for (const j of jobs) {
    const pt = j.lat != null && j.lng != null ? project(j.lat, j.lng) : null;
    if (!pt) {
      offMap++;
      continue;
    }
    const key = `${j.lat!.toFixed(5)},${j.lng!.toFixed(5)}`;
    const place = byKey.get(key) ?? { key, ...pt, phase: null, jobs: [] };
    place.jobs.push(j);
    if (place.jobs.length === 1 || rank(j.phase) < rank(place.phase)) place.phase = j.phase ?? null;
    byKey.set(key, place);
  }
  // Highest-ranked phase last, so it draws on top where dots touch.
  const places = [...byKey.values()].sort((a, b) => rank(b.phase) - rank(a.phase));
  return { places, offMap };
}
